<script setup lang="ts">
import { computed,ref } from 'vue'
import { useRouter } from 'vue-router'
import PageHeader from '../components/layout/PageHeader.vue'
import Toast from '../components/common/Toast.vue'
import ConfirmDialog from '../components/common/ConfirmDialog.vue'
import MapPreview from '../components/map/MapPreview.vue'
import { useSimpleFlowStore } from '../stores/simpleFlowStore'
import { useTaskStore } from '../stores/taskStore'
import { functions } from '../services/profile'
import { GEOMETRY_SOURCE } from '../services/simplePipeline'
import type { PlotCollection } from '../types'
const task=useTaskStore(),flow=useSimpleFlowStore(),router=useRouter(),search=ref(''),message=ref(''),confirm=ref(false),highlight=ref('')
const columns=computed(()=>task.template?.columns.filter(c=>`${c.header} ${c.key}`.includes(search.value))||[])
const mapped=computed(()=>task.template?.columns.filter(c=>flow.mapping[c.key]).length||0)
const canGenerate=computed(()=>!!flow.source&&!flow.checking&&!!flow.report&&!flow.checkError&&!flow.blocking&&(task.activeId!=='village-boundary'||!flow.villagePreview.errors.length))
const warnings=computed(()=>flow.report?.issues.filter(i=>i.level==='warn').length||0)
const mapData=computed<PlotCollection>(()=>({type:'FeatureCollection',features:(flow.source?.features||[]).flatMap((f,i)=>{const rows=flow.report?.issues.filter(q=>q.level==='block').flatMap(q=>q.rows)||[];return rows.includes(i+1)?[]:[{...f,properties:{rowId:`source-${i+1}`}}]})}))
function generate(){try{flow.generate();router.push('/output')}catch(e){message.value=String(e)}}
function next(){if(warnings.value)confirm.value=true;else generate()}
function sample(key:string){const selected=flow.mapping[key];if(!selected)return '留空';if(selected===GEOMETRY_SOURCE)return '从源几何转为 WKT';const raw=selected.startsWith('field:')?selected.slice(6):selected;const value=flow.source?.features.find(f=>f.properties[raw]!==null&&f.properties[raw]!==undefined)?.properties[raw];return value===null||value===undefined?'来源为空':typeof value==='object'?JSON.stringify(value):String(value)}
</script>
<template><PageHeader title="字段映射" description="选择原始字段对应的模板列；未映射项留空，表头完整保留。"><RouterLink class="button secondary" to="/">重新上传</RouterLink><button :disabled="!canGenerate" @click="next">生成矢量和表格 →</button></PageHeader><div v-if="!flow.source" class="panel empty"><h2>请先上传原始矢量</h2><RouterLink class="button" to="/">返回上传</RouterLink></div><template v-else><div class="function-context"><span>{{flow.fileName}}</span><select v-model="task.activeId" aria-label="目标表格模板"><option v-for="f in functions" :key="f.id" :value="f.id">{{f.name}}</option></select><span>已映射 {{mapped}} / {{task.template?.columns.length}} 字段 · 其余输出空值</span></div><Toast :message="message"/><section v-if="task.activeId==='village-boundary'" class="panel village-grouping"><div class="section-heading"><div><h2>按村分表</h2><p>每个村一个表格，同村多个要素保留多行。</p></div><span class="badge neutral">{{flow.villagePreview.groups.length}} 个村</span></div><label>村标识依据 <select aria-label="村标识依据" :value="flow.villageGroupField" @change="flow.setVillageGroup(($event.target as HTMLSelectElement).value)"><option value="">使用已映射的行政区划编码</option><option v-for="f in flow.fields" :key="f" :value="f">原始字段：{{f}}</option></select></label><p class="hint">请选择能唯一区分村的字段，避免仅凭同名村合并。该字段只用于分表，不会回填未映射的模板列。</p><div v-if="flow.villagePreview.errors.length" class="notice">{{flow.villagePreview.errors[0]}}<span v-if="flow.villagePreview.errors.length>1">（共 {{flow.villagePreview.errors.length}} 项）</span></div><div v-else class="raw-tags"><span v-for="g in flow.villagePreview.groups" :key="g.key">{{g.name}} · {{g.key}} · {{g.rows.length}} 个要素</span></div></section><div class="mapping-workspace"><section class="panel"><div class="section-heading"><h2>表格字段 ← 原始字段</h2><input v-model="search" aria-label="搜索模板字段" placeholder="搜索模板字段"></div><div class="table-scroll"><table><thead><tr><th>模板字段</th><th>选择原始字段</th><th>预览值</th></tr></thead><tbody><tr v-for="c in columns" :key="c.key"><td class="wrap"><strong>{{c.header}}</strong></td><td><select :aria-label="`映射 ${c.header}`" :value="flow.mapping[c.key]||''" @change="flow.map(c.key,($event.target as HTMLSelectElement).value)"><option value="">不映射，留空</option><option v-if="c.key==='geom_wkt'" :value="GEOMETRY_SOURCE">源矢量几何 → WKT</option><option v-for="f in flow.fields" :key="f" :value="`field:${f}`">{{f}}</option></select></td><td><span class="cell-text" :title="sample(c.key)">{{sample(c.key)}}</span></td></tr><tr v-if="!columns.length"><td colspan="3" class="empty">无匹配字段</td></tr></tbody></table></div></section><aside><section class="panel"><div class="section-heading"><h2>拓扑检查</h2><button class="secondary small" :disabled="flow.checking" @click="flow.runTopology">重新检查</button></div><div v-if="flow.checking" class="notice" role="status">正在检查几何与地块间关系，可以继续映射字段…</div><div v-else-if="flow.checkError" class="notice">{{flow.checkError}}</div><template v-else-if="flow.report"><div class="topology-summary"><span class="badge block">阻断 {{flow.blocking}}</span><span class="badge warn">警告 {{warnings}}</span><span class="badge neutral">已检查 {{flow.report.checked}} 个要素</span></div><p v-if="!flow.report.issues.length" class="notice success-notice">本次检查未发现拓扑问题，可以生成。</p><div class="topology-issues"><div v-for="(issue,i) in flow.report.issues" :key="i" class="topology-item"><span class="badge" :class="issue.level">{{issue.level==='block'?'阻断':'警告'}}</span><strong>{{issue.type}}</strong><p>第 {{issue.rows.join('、')}} 个要素：{{issue.message}}</p><button v-if="issue.level==='warn'" class="text-button" @click="highlight=`source-${issue.rows[0]}`">定位相关地块</button></div></div><p v-if="flow.blocking" class="hint">先修复源矢量中的阻断问题，再重新上传。不会自动修复或丢弃问题要素。</p></template><details class="help-details"><summary>检查范围</summary><p class="hint">检查空几何、环闭合、自相交、无效面、重复面和重叠；共边允许。无项目边界时不检查缝隙，不替代平台验收。</p></details></section><section v-if="flow.report" class="panel map-panel"><h2>地块预览</h2><MapPreview :geojson="mapData" :highlight-row-id="highlight"/><p class="hint">有阻断几何的要素不绘制，原始数据仍完整保留。</p></section></aside></div></template><ConfirmDialog v-if="confirm" title="存在拓扑警告，继续生成？" message="重复或重叠地块将原样保留，检查报告与生成结果同时保留。请确认已了解这些问题。" @cancel="confirm=false" @confirm="confirm=false;generate()"/></template>
